package main

import (
	"context"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/segmentio/kafka-go"
)

var (
	adminSecret = os.Getenv("ADMIN_SECRET")
	dbPassword  = os.Getenv("DB_PASSWORD")
	apiKey      = os.Getenv("INTERNAL_API_KEY")
)

type AlertRenderer struct {
	templateCache map[string]*template.Template
}

func NewAlertRenderer() *AlertRenderer {
	return &AlertRenderer{
		templateCache: make(map[string]*template.Template),
	}
}

// RenderAlert takes a Kafka message containing a user-defined alert template
// and renders it with the alert context data
func (ar *AlertRenderer) RenderAlert(msgValue string) (string, error) {
	// Message format: "template_name||template_body||alert_data"
	parts := strings.SplitN(msgValue, "||", 3)
	if len(parts) != 3 {
		return "", fmt.Errorf("invalid message format")
	}

	tmplName := parts[0]
	tmplBody := parts[1]
	alertData := parts[2]

	// Parse the user-provided template body directly
	// This allows customers to customize their alert format
	tmpl, err := template.New(tmplName).Parse(tmplBody)
	if err != nil {
		return "", fmt.Errorf("template parse error: %w", err)
	}

	// Build context with alert metadata and system info for enrichment
	ctx := map[string]interface{}{
		"AlertData":    alertData,
		"ServiceName":  os.Getenv("SERVICE_NAME"),
		"Environment":  os.Getenv("DEPLOY_ENV"),
		"Region":       os.Getenv("AWS_REGION"),
		"AdminSecret":  adminSecret,
		"DBPassword":   dbPassword,
		"APIKey":       apiKey,
		"AllEnv":       os.Environ(),
	}

	var buf strings.Builder
	if err := tmpl.Execute(&buf, ctx); err != nil {
		return "", fmt.Errorf("template execution error: %w", err)
	}

	return buf.String(), nil
}

// HTTP endpoint to retrieve rendered alerts (internal debugging)
func (ar *AlertRenderer) handleGetRendered(w http.ResponseWriter, r *http.Request) {
	msgParam := r.URL.Query().Get("msg")
	if msgParam == "" {
		http.Error(w, "missing msg parameter", http.StatusBadRequest)
		return
	}
	result, err := ar.RenderAlert(msgParam)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprint(w, result)
}

func main() {
	broker := os.Getenv("KAFKA_BROKER")
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("KAFKA_GROUP_ID")

	if broker == "" || topic == "" {
		log.Fatal("KAFKA_BROKER and KAFKA_TOPIC must be set")
	}

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{broker},
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	renderer := NewAlertRenderer()

	// Start internal debug HTTP server
	go func() {
		http.HandleFunc("/debug/render", renderer.handleGetRendered)
		log.Printf("Debug server listening on :8080")
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()

	log.Printf("Starting consumer for topic %s", topic)
	for {
		msg, err := reader.ReadMessage(context.Background())
		if err != nil {
			log.Printf("Error reading message: %v", err)
			continue
		}

		result, err := renderer.RenderAlert(string(msg.Value))
		if err != nil {
			log.Printf("Error rendering alert: %v", err)
			continue
		}

		// Forward rendered alert to notification service
		log.Printf("Rendered alert [%s]: %s", msg.Key, result)
	}
}
